const src = $json || {};
const body = (src.body && typeof src.body === 'object') ? src.body : src;
const contact_id = String(body.contact_id || '').trim();
const phone = String(body.phone || '').trim();
const workflow_id = String(body.workflow_id || '').trim();
const template_id = String(body.template_id || '').trim();
const message_body = String(body.message_body || '').trim();
const simulate = body.simulate === undefined ? true : !!body.simulate;
const yyyymmdd = new Date().toISOString().slice(0,10).replace(/-/g, '');

function hashHex(input) {
  let h = 2166136261;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

const message_hash = hashHex(`${contact_id}|${workflow_id}|${template_id}|${yyyymmdd}`);
const q = (v) => `'${String(v ?? '').replace(/'/g, "''")}'`;

const claimSql = `
CREATE TABLE IF NOT EXISTS report_sms_sent (
  id BIGSERIAL PRIMARY KEY,
  contact_id TEXT NOT NULL,
  phone TEXT,
  workflow_id TEXT NOT NULL,
  template_id TEXT,
  message_hash TEXT NOT NULL,
  provider_response JSONB,
  sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX IF NOT EXISTS report_sms_sent_uq
  ON report_sms_sent (contact_id, workflow_id, message_hash);

WITH ins AS (
  INSERT INTO report_sms_sent (contact_id, phone, workflow_id, template_id, message_hash)
  VALUES (${q(contact_id)}, ${q(phone)}, ${q(workflow_id)}, ${q(template_id)}, ${q(message_hash)})
  ON CONFLICT (contact_id, workflow_id, message_hash) DO NOTHING
  RETURNING id, sent_at
), existing AS (
  SELECT id, sent_at
  FROM report_sms_sent
  WHERE contact_id = ${q(contact_id)}
    AND workflow_id = ${q(workflow_id)}
    AND message_hash = ${q(message_hash)}
  ORDER BY id DESC
  LIMIT 1
)
SELECT
  CASE WHEN EXISTS(SELECT 1 FROM ins) THEN true ELSE false END AS inserted,
  COALESCE((SELECT id::text FROM ins), (SELECT id::text FROM existing), '') AS id,
  COALESCE((SELECT sent_at::text FROM ins), (SELECT sent_at::text FROM existing), '') AS sent_at;
`;

return [{ json: { contact_id, phone, workflow_id, template_id, message_body, simulate, message_hash, claimSql } }];

const row = $json || {};
const ctx = $('Prepare Request').first().json;
const q = (v) => `'${String(v ?? '').replace(/'/g, "''")}'`;

if (!row.inserted) {
  return [{ json: {
    status: 'duplicate',
    sent_at: row.sent_at || null,
    id: row.id || null,
    provider_response: null,
    updateSql: 'SELECT 1;'
  } }];
}

let providerResponse;
if (ctx.simulate) {
  providerResponse = { id: 'stubsim', status: 'queued', simulate: true };
} else {
  const token = String($env.SIMPLETEXTING_API_KEY || '').trim();
  if (!token) {
    return [{ json: {
      status: 'error',
      error: 'missing_simpletexting_api_key',
      id: row.id || null,
      updateSql: 'SELECT 1;'
    } }];
  }

  const sendRes = await $httpRequest({
    method: 'POST',
    url: 'https://api-app2.simpletexting.com/v2/api/messages',
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/json',
      'Content-Type': 'application/json',
    },
    body: {
      contactPhone: String(ctx.phone || '').replace(/\D/g, '').slice(-10),
      mode: 'SINGLE_SMS_STRICTLY',
      text: ctx.message_body,
    },
    json: true,
  });
  providerResponse = sendRes || {};
}

const updateSql = `UPDATE report_sms_sent
SET provider_response = ${q(JSON.stringify(providerResponse))}::jsonb
WHERE id = ${q(row.id)};`;

return [{ json: {
  status: 'sent',
  id: row.id,
  sent_at: row.sent_at || null,
  provider_response: providerResponse,
  updateSql
} }];

const out = $('Finalize Send').first().json || {};
return [{ json: {
  status: out.status || null,
  id: out.id || null,
  sent_at: out.sent_at || null,
  provider_response: out.provider_response || null,
  error: out.error || null,
} }];

